cd /workspace/tests && python3 - <<'EOF'
import sys, random
sys.path.insert(0,'/workspace/submission')
from sortedcontainers import RankCounter
random.seed(5)
def check(c, ref, tag):
    for i,(k,cnt) in enumerate(zip(c._keys, c._cnts)):
        if len(k)!=len(cnt) or c._lens[i]!=len(k):
            print("INCONSISTENT", tag, i, len(k), len(cnt), c._lens[i], c._total)
            print(" keys", k[:10]); print(" cnts", cnt[:10])
            raise SystemExit(1)
c = RankCounter(); ref={}
for step in range(5000):
    k = random.randint(0,500)
    c.increment(k); ref[k]=ref.get(k,0)+1
    if step % 500 == 0:
        ck = c.checkpoint(); c2 = RankCounter(ck); check(c2, None, 'restored')
    check(c, ref, 'step%d'%step)
    if step % 7 == 0:
        q = random.randint(0,500)
        assert c.count_le(q) == sum(v for kk,v in ref.items() if kk<=q), (step,q)
print("ok")
EOF
